// Enhanced email classification
const emailContent = {
  from: $json.from,
  subject: $json.subject,
  body: $json.textPlain || $json.snippet,
  date: $json.date,
  messageId: $json.id
};

// Check if this is job-search related
const jobSearchKeywords = [
  'interview', 'schedule', 'available', 'calendar',
  'position', 'role', 'application', 'candidate',
  'recruiter', 'talent', 'careers', 'hiring',
  'opportunity', 'interested', 'next steps'
];

const isJobRelated = jobSearchKeywords.some(keyword => 
  emailContent.subject.toLowerCase().includes(keyword) ||
  emailContent.body.toLowerCase().includes(keyword) ||
  emailContent.from.toLowerCase().includes(keyword)
);

if (!isJobRelated) {
  return { skipEmail: true, reason: 'Not job search related' };
}

return {
  ...emailContent,
  needsAIAnalysis: true
};

// Parse Claude's response
let analysis;
try {
  const responseText = $json.content || $json.text || $json.response;
  analysis = JSON.parse(responseText);
} catch (error) {
  analysis = {
    category: 'OTHER',
    confidence: 50,
    reasoning: 'Failed to parse AI response: ' + error.message
  };
}

// Get original email data
const originalEmail = $('Filter Job-Related Emails').item.json;

const result = {
  ...analysis,
  originalEmail: originalEmail,
  processedAt: new Date().toISOString()
};

return result;

// Generate 3 available interview time slots based on calendar availability
const now = new Date();
const busyTimes = $json.calendars?.primary?.busy || [];

// Helper function to check if a time slot conflicts with busy periods
function isTimeSlotFree(startTime, endTime) {
  const start = new Date(startTime);
  const end = new Date(endTime);

  return !busyTimes.some(busy => {
    const busyStart = new Date(busy.start);
    const busyEnd = new Date(busy.end);

    // Check if there's any overlap
    return (start < busyEnd && end > busyStart);
  });
}

// Helper function to format date/time
function formatSlot(date) {
  const options = { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric', 
    hour: 'numeric', 
    minute: '2-digit',
    timeZoneName: 'short'
  };
  return date.toLocaleDateString('en-US', options);
}

// Generate business days and time slots
const availableSlots = [];
let currentDate = new Date(now);
currentDate.setDate(currentDate.getDate() + 1); // Start tomorrow

// Preferred time slots: 10 AM, 2 PM, 4 PM
const preferredHours = [10, 14, 16];

for (let days = 0; days < 14 && availableSlots.length < 10; days++) {
  const dayOfWeek = currentDate.getDay();

  // Skip weekends
  if (dayOfWeek !== 0 && dayOfWeek !== 6) {
    for (const hour of preferredHours) {
      const slotStart = new Date(currentDate);
      slotStart.setHours(hour, 0, 0, 0);

      const slotEnd = new Date(slotStart);
      slotEnd.setHours(hour + 1, 0, 0, 0); // 1 hour duration

      if (isTimeSlotFree(slotStart, slotEnd)) {
        availableSlots.push({
          startTime: slotStart,
          endTime: slotEnd,
          formatted: formatSlot(slotStart),
          hour: hour,
          day: currentDate.toDateString()
        });
      }
    }
  }

  currentDate.setDate(currentDate.getDate() + 1);
}

// Select 3 diverse slots (different days, different times)
const selectedSlots = [];
const usedDays = new Set();
const usedHours = new Set();

for (const slot of availableSlots) {
  if (selectedSlots.length >= 3) break;

  const dayKey = slot.day;
  const hourKey = slot.hour;

  // Prefer slots on different days and different times
  if (!usedDays.has(dayKey) || !usedHours.has(hourKey)) {
    selectedSlots.push(slot);
    usedDays.add(dayKey);
    usedHours.add(hourKey);
  }
}

// If we don't have 3 slots yet, fill with any available
while (selectedSlots.length < 3 && selectedSlots.length < availableSlots.length) {
  for (const slot of availableSlots) {
    if (selectedSlots.length >= 3) break;
    if (!selectedSlots.some(s => s.startTime.getTime() === slot.startTime.getTime())) {
      selectedSlots.push(slot);
    }
  }
}

// Get original email and AI analysis data
const emailData = $('Parse Classification Result').item.json;

return {
  ...emailData,
  availableSlots: selectedSlots,
  totalSlotsFound: availableSlots.length,
  slotSelectionToken: Math.random().toString(36).substring(2, 15),
  calendarCheckedAt: new Date().toISOString()
};
